export function documentReady(fn: () => void) {
  if (document.readyState === "complete" || document.readyState === "interactive") {
    // Use setTimeout instead of eval to delay the function execution by 1ms
    setTimeout(fn, 1);
  } else {
    // Use addEventListener to bind the function to DOMContentLoaded event
    document.addEventListener("DOMContentLoaded", fn);
  }
}
